import assert from'node:assert/strict';import path from'node:path';import{execFileSync}from'node:child_process';import{readFile,writeFile,copyFile}from'node:fs/promises';import{load}from'cheerio';import{chromium}from'playwright';import{publicRatingCount}from'../../engine/commerce.mjs';import{parseContent,YAML}from'../../scripts/source-project.mjs';import{serveStatic}from'../../engine/static.mjs';import{run}from'../../engine/pipeline.mjs';
const root=path.resolve('artifacts/platform/woocommerce-complete'),project=path.join(root,'project'),source='http://127.0.0.1:9427',files=['product-studio-mug','product-workshop-shirt'].map(s=>path.join(project,'content/wp-product/'+s+'.md')),saved=await Promise.all(files.map(f=>readFile(f,'utf8')));
const php=(code,data='')=>execFileSync('php',['-r',"$_SERVER['HTTP_HOST']='127.0.0.1:9427';require $argv[1].'/wp-load.php';"+code,path.resolve('work/woo/wordpress'),data],{encoding:'utf8',env:{...process.env,FIXTURE_DB_HOST:'localhost:'+path.resolve('work/woo/mysql.sock'),FIXTURE_DB_DIR:path.resolve('work/woo/databases')}}).trim();
const snapshot="$out=[];foreach([20,21]as$id){$p=wc_get_product($id);$out[$id]=['ratings'=>$p->get_rating_counts(),'average'=>$p->get_average_rating(),'reviews'=>$p->get_review_count()];}echo json_encode($out);",set="foreach(json_decode($argv[2],true)as$id=>$v){$p=wc_get_product($id);$p->set_rating_counts($v['ratings']);$p->set_average_rating($v['average']);$p->set_review_count($v['reviews']);$p->save();wc_delete_product_transients($id);}";let baseline,browser,server;
try{baseline=php(snapshot);php(set,JSON.stringify({20:{ratings:{4:3},average:'4',reviews:4},21:{ratings:{4:2},average:'4',reviews:9}}));
 const captured=[];for(let i=0;i<files.length;i++){const parsed=parseContent(saved[i],files[i]),id=parsed.meta.product.id,row=await(await fetch(source+'/wp-json/wc/store/v1/products/'+id)).json(),html=await(await fetch(source+'/product/'+(id===20?'studio-mug':'workshop-shirt')+'/')).text();const count=publicRatingCount(html,{...parsed.meta.product,average_rating:row.average_rating});assert.equal(count,id===20?3:2);assert.notEqual(count,row.review_count);parsed.meta.product.average_rating=row.average_rating;parsed.meta.product.review_count=row.review_count;parsed.meta.product.rating_count=count;await writeFile(files[i],'---\n'+YAML.stringify(parsed.meta)+'---\n'+parsed.body);captured.push({id,ratingCount:count,reviewCount:row.review_count});}
 const gen=await readFile('engine/generate.mjs','utf8');for(const m of gen.matchAll(/\["(scripts\/[^"\n]+|vendor\/export-source\.mjs)", "([^"\n]+)"\]/g))await copyFile(path.resolve(m[1]),path.join(project,m[2]));await run(process.execPath,['scripts/build.mjs'],{cwd:project,timeout:120000});const $=load(await(await fetch(source+'/shop/?orderby=rating')).text()),expected=$('ul.products > li h2').map((_,e)=>$(e).text()).get();assert.deepEqual(expected,['Studio Mug','Workshop Shirt']);server=await serveStatic(path.join(project,'output'));browser=await chromium.launch({channel:'chrome'});const page=await browser.newPage();await page.route('**/*',r=>r.request().method()==='GET'&&new URL(r.request().url()).origin===server.url?r.continue():r.abort());await page.goto(server.url+'/shop/?orderby=rating');await page.waitForFunction(()=>document.querySelector('form.woocommerce-ordering [role=status]')?.textContent.includes('products, page'));assert.deepEqual(await page.locator('ul.products > li h2').allTextContents(),expected);const report={scope:'Owned WooCommerce positive-rating tie and distinct review counts; public markup capture and native ordering',captured,expected,aiCalls:0};await writeFile(path.join(root,'rating-count-check.json'),JSON.stringify(report,null,2)+'\n');console.log(JSON.stringify(report));
}finally{await browser?.close();await server?.close();if(baseline){php(set,baseline);assert.deepEqual(JSON.parse(php(snapshot)),JSON.parse(baseline));}for(let i=0;i<files.length;i++)await writeFile(files[i],saved[i]);await run(process.execPath,['scripts/build.mjs'],{cwd:project,timeout:120000});}
